const authBase = '/api/auth'

export const ENDPOINTS = Object.freeze({
  PUBLIC: Object.freeze({
    CATALOG: '/api/public/catalog',
    PRODUCTS: '/api/public/products',
    PRODUCT: (id) => `/api/public/products/${encodeURIComponent(id)}`,
    RELATED: (id) => `/api/public/products/${encodeURIComponent(id)}/related`,
  }),
  ADMIN: Object.freeze({
    USERS: '/api/admin/users',
    USER: (id) => `/api/admin/users/${encodeURIComponent(id)}`,
    USER_EMAIL: (id) => `/api/admin/users/${encodeURIComponent(id)}/email`,
    USER_DEACTIVATE: (id) => `/api/admin/users/${encodeURIComponent(id)}/deactivate`,
    USER_REACTIVATE: (id) => `/api/admin/users/${encodeURIComponent(id)}/reactivate`,
  }),
  CATALOG: Object.freeze({
    CATEGORIES: '/api/catalog/categories',
    CATEGORY: (id) => `/api/catalog/categories/${encodeURIComponent(id)}`,
    CATEGORY_DEACTIVATE: (id) => `/api/catalog/categories/${encodeURIComponent(id)}/deactivate`,
    CATEGORY_REACTIVATE: (id) => `/api/catalog/categories/${encodeURIComponent(id)}/reactivate`,
    SUBCATEGORIES: '/api/catalog/subcategories',
    SUBCATEGORY: (id) => `/api/catalog/subcategories/${encodeURIComponent(id)}`,
    PRODUCTS: '/api/catalog/products',
    PRODUCT: (id) => `/api/catalog/products/${encodeURIComponent(id)}`,
    PRODUCT_VARIANTS: (id) => `/api/catalog/products/${encodeURIComponent(id)}/variants`,
    PRODUCT_VARIANT: (id, variantId) => `/api/catalog/products/${encodeURIComponent(id)}/variants/${encodeURIComponent(variantId)}`,
    PRODUCT_VARIANT_DEACTIVATE: (id, variantId) => `/api/catalog/products/${encodeURIComponent(id)}/variants/${encodeURIComponent(variantId)}/deactivate`,
    PRODUCT_VARIANT_REACTIVATE: (id, variantId) => `/api/catalog/products/${encodeURIComponent(id)}/variants/${encodeURIComponent(variantId)}/reactivate`,
    PRODUCT_DEACTIVATE: (id) => `/api/catalog/products/${encodeURIComponent(id)}/deactivate`,
    PRODUCT_REACTIVATE: (id) => `/api/catalog/products/${encodeURIComponent(id)}/reactivate`,
    PRODUCT_IMAGES: (id) => `/api/catalog/products/${encodeURIComponent(id)}/images`,
    PRODUCT_IMAGE: (id, imageId) => `/api/catalog/products/${encodeURIComponent(id)}/images/${encodeURIComponent(imageId)}`,
    PRODUCT_IMAGE_PRIMARY: (id, imageId) => `/api/catalog/products/${encodeURIComponent(id)}/images/${encodeURIComponent(imageId)}/primary`,
    PRODUCT_IMAGES_ORDER: (id) => `/api/catalog/products/${encodeURIComponent(id)}/images/order`,
    CHARACTERISTICS: '/api/catalog/characteristics',
    CHARACTERISTIC: (id) => `/api/catalog/characteristics/${encodeURIComponent(id)}`,
  }),
  AUTH: Object.freeze({
    CHANGE_PASSWORD: `${authBase}/change-password`,
    CSRF: `${authBase}/csrf`,
    LOGIN: `${authBase}/login`,
    REFRESH: `${authBase}/refresh`,
    LOGOUT: `${authBase}/logout`,
    MFA_CANCEL: `${authBase}/mfa/cancel`,
    MFA_VERIFY: `${authBase}/mfa/login/verify`,
    MFA_RESEND: `${authBase}/mfa/login/resend`,
    MFA_STATUS: `${authBase}/mfa/status`,
    MFA_ENABLE_START: `${authBase}/mfa/enable/start`,
    MFA_ENABLE_CONFIRM: `${authBase}/mfa/enable/confirm`,
    MFA_DISABLE_START: `${authBase}/mfa/disable/start`,
    MFA_DISABLE_CONFIRM: `${authBase}/mfa/disable/confirm`,
    MFA_SETTINGS_RESEND: `${authBase}/mfa/settings/resend`,
    ME: `${authBase}/me`,
    FORGOT_PASSWORD: `${authBase}/forgot-password`,
    RESET_PASSWORD: `${authBase}/reset-password`,
    VALIDATE_RESET_TOKEN: (token) =>
      `${authBase}/reset-password/validate?${new URLSearchParams({ token })}`,
  }),
})
